// Minter decides the key a row is stored under. It is asked once per Add,
// for an entity whose key is a uuid, and only for those.
//
// `given` is the key the request named and `ok` says whether it named
// one. A minter is free to refuse what it was given -- an error it
// answers with is the caller's answer, so it may be a status -- and free
// to ignore it, though a request whose key is quietly replaced is a
// request that was answered with something it did not ask for.
//
// `entity` is the full name of the message, such as "app.Robot".
//
// A nil Minter keeps what a request named and makes up a v4 for a request
// that named nothing, which is what these servers did before there was
// anywhere to say otherwise.
type Minter interface {
	Mint(ctx context.Context, entity string, given uuid.UUID, ok bool) (uuid.UUID, error)
}

// MinterFunc is a [Minter] written as a function.
type MinterFunc func(ctx context.Context, entity string, given uuid.UUID, ok bool) (uuid.UUID, error)

func (f MinterFunc) Mint(ctx context.Context, entity string, given uuid.UUID, ok bool) (uuid.UUID, error) {
	return f(ctx, entity, given, ok)
}

// mint is what the generated Add asks. It is here rather than at each
// call site so that the answer to a nil Minter is written once.
func mint(ctx context.Context, m Minter, entity string, given uuid.UUID, ok bool) (uuid.UUID, error) {
	if m == nil {
		if ok {
			return given, nil
		}
		return uuid.New(), nil
	}

	return m.Mint(ctx, entity, given, ok)
}

// Clock is what these servers ask when they stamp a time -- `date_created`,
// the version field, the one an erase marks.
//
// It exists so that a test can say what time it is, the way [Minter] lets
// one say what a key is. Those two are the whole of what makes a generated
// server's answer unpredictable, and an answer that cannot be predicted is
// one a test has to take apart field by field.
//
// It is **not** about clock skew. What a deployment's clocks say to each
// other is the deployment's business, and nothing here corrects it.
//
// A nil Clock is `time.Now`, which is the difference between this and
// [Minter]: a row has to be stamped with something, so there is no state
// in which answering nothing is right.
//
//	s, err := bare.NewServer(db, bare.WithClock(func() time.Time { return at }))
type Clock func() time.Time

// now is what a stamp reads, and `time.Now` when nothing was handed in.
//
// UTC because a stamp is compared and ordered rather than shown, and a
// time carrying a zone is one that compares equal to itself written
// another way -- which is true and is not what anybody reading the
// comparison expects. A Clock is free to answer in any zone; this is
// what is stored.
func (s Store) now() time.Time {
	if s.Now == nil {
		return time.Now().UTC()
	}

	return s.Now().UTC()
}

// ItemError is `err`, about the item at `i` of a call that carries many --
// an AddMany -- said so that its caller can tell which: in the code `err`
// had, after `items[i]: ` in the message, and, for an InvalidArgument, with
// every field of its google.rpc.BadRequest under `items[i]` -- or one that
// names the item, when it had none. A layer that refuses one item of many
// answers with this, as the generated AddMany does.
func ItemError(i int, err error) error {
	if err == nil {
		return nil
	}

	at := fmt.Sprintf("items[%d]", i)
	st := status.Convert(err)
	out := status.New(st.Code(), at+": "+st.Message())

	details := []protoadapt.MessageV1{}
	named := false
	for _, d := range st.Details() {
		if b, ok := d.(*errdetails.BadRequest); ok {
			vs := make([]*errdetails.BadRequest_FieldViolation, len(b.GetFieldViolations()))
			for k, v := range b.GetFieldViolations() {
				field := at
				switch f := v.GetField(); {
				case f == "":
				case f[0] == '[':
					field += f
				default:
					field += "." + f
				}
				vs[k] = &errdetails.BadRequest_FieldViolation{Field: field, Description: v.GetDescription()}
			}
			details = append(details, &errdetails.BadRequest{FieldViolations: vs})
			named = true
			continue
		}
		if m, ok := d.(protoadapt.MessageV1); ok {
			details = append(details, m)
		}
	}
	if !named && st.Code() == codes.InvalidArgument {
		details = append(details, &errdetails.BadRequest{
			FieldViolations: []*errdetails.BadRequest_FieldViolation{{Field: at, Description: st.Message()}},
		})
	}
	if len(details) == 0 {
		return out.Err()
	}

	with, err := out.WithDetails(details...)
	if err != nil {
		return out.Err()
	}
	return with.Err()
}

// NewServer refuses a client whose dialect this backend does not write
// SQL for.
//
// An engine that speaks one of the written dialects under a different
// name -- a PostgreSQL-compatible server -- is named when the connection
// is opened, which is where saying so belongs: everything the client does
// is rendered for that dialect, not just what this server writes.
//
// That set is also what a soft erasure needs, so this is the whole
// check. Account, AuthBinding, Connection, Holder, Project, Session, Task and TaskLink free the names they held when a row
// is erased, which is a unique index covering only the rows that are
// still there -- a partial index, and the dialects above are the ones
// that have one. MySQL does not, and ent writes the annotation out for
// it rather than refusing, so the index would come up covering every
// row and a freed name would stay taken with nothing to say so.
func NewServer(db *ent.Client, opts ...Option) (Server, error) {
	s := Server{Store: Store{Db: db}}
	for _, opt := range opts {
		if err := opt(&s); err != nil {
			return Server{}, err
		}
	}
	if d := db.Dialect(); !entpatch.Supports(d) {
		return Server{}, fmt.Errorf("%w: %s", entpatch.ErrDialect, d)
	}
	return s, nil
}

// WithDriver answers with a server that runs through drv, and is this one
// in every other way.
//
// It is how a caller puts several servers on one transaction: begin one
// with enttx and rebind the stack onto the driver it answers with.
//
// The dialect is checked again rather than assumed. A transaction wraps
// the connection it was begun on, so it carries the same dialect -- but
// this takes a driver from anywhere, and what NewServer refused at the
// start should not become reachable by going around it.
func (s Server) WithDriver(drv dialect.Driver) (resource.Server, error) {
	db := s.Db.WithDriver(drv)
	if d := db.Dialect(); !entpatch.Supports(d) {
		return nil, fmt.Errorf("%w: %s", entpatch.ErrDialect, d)
	}
	s.Db = db
	return s, nil
}

